 3	/**
 4	 * Stable counting sort for integer arrays.
 5	 */
 6	public final class CountingSort {
 7	
 8	    private CountingSort() {
 9	    }
10	
11	    public static int[] countSort(int[] values) {
12	        return sortedCopy(values);
13	    }
14	
15	    public static int[] sort(int[] values) {
16	        return sortedCopy(values);
17	    }
18	
19	    public static int[] sortedCopy(int[] values) {
20	        Objects.requireNonNull(values, "values");
21	
22	        if (values.length == 0) {
23	            return new int[0];
24	        }
25	
26	        Range range = findRange(values);
27	        int[] prefixCounts = buildPrefixCounts(values, range);
28	        return buildSortedArray(values, prefixCounts, range);
29	    }
30	
31	    private static Range findRange(int[] values) {
32	        int minValue = values[0];
33	        int maxValue = values[0];
34	
35	        for (int i = 1; i < values.length; i++) {
36	            int value = values[i];
37	            if (value < minValue) {
38	                minValue = value;
39	            }
40	            if (value > maxValue) {
41	                maxValue = value;
42	            }
43	        }
44	
45	        return new Range(minValue, maxValue);
46	    }
47	
48	    private static int[] buildPrefixCounts(int[] values, Range range) {
49	        int[] counts = new int[range.size()];
50	
51	        for (int value : values) {
52	            counts[range.indexOf(value)]++;
53	        }
54	
55	        for (int i = 1; i < counts.length; i++) {
56	            counts[i] += counts[i - 1];
57	        }
58	
59	        return counts;
60	    }
61	
62	    private static int[] buildSortedArray(int[] values, int[] prefixCounts, Range range) {
63	        int[] sortedValues = new int[values.length];
64	
65	        for (int i = values.length - 1; i >= 0; i--) {
66	            int value = values[i];
67	            int countIndex = range.indexOf(value);
68	            sortedValues[prefixCounts[countIndex] - 1] = value;
69	            prefixCounts[countIndex]--;
70	        }
71	
72	        return sortedValues;
73	    }
74	
75	    private record Range(int minValue, int maxValue) {
76	        private int size() {
77	            long size = (long) maxValue - minValue + 1;
78	            if (size > Integer.MAX_VALUE) {
79	                throw new IllegalArgumentException(
80	                    "Counting sort range is too large to index."
81	                );
82	            }
83	
84	            return (int) size;
85	        }
86	
87	        private int indexOf(int value) {
88	            return value - minValue;
89	        }
90	    }
91	}

